/**
 * IndiaMarketSessionService (spec §9, §10). The backend is authoritative: all
 * session logic runs in Asia/Kolkata (computed from UTC — never the client
 * clock). Knows weekday, exchange holidays (NSE official calendar, overridable),
 * pre-open state, market open/close and per-segment tradability.
 *
 * When the market is closed: no new ticks/signals/trades are generated by the
 * module — the UI keeps displaying the last real price and clearly says
 * MARKET CLOSED.
 */
import type { IndiaMarketSessionInfo, IndiaMarketStatus } from '@fx/shared';
import { INDIA_SESSION, INDIA_CHANNELS, INDIA_COLLECTIONS } from '@fx/shared';
import { DataStore } from '../db/store';
import { EventEmitter } from 'events';
import * as fs from 'fs';
import * as path from 'path';
import { indiaConfig } from './config';

/**
 * Official NSE holiday calendar (reference data published by NSE). Kept as a
 * data table because the exchange publishes it once a year; a JSON file
 * override (INDIA_HOLIDAY_FILE) or entries in the IndiaMarketSession collection
 * extend it. This is reference metadata, NOT a fabricated market session.
 *
 * Sources:
 *  - 2025: NSE/CMTR/65587 (Dec 13 2024) — 14 trading holidays. Ganesh Chaturthi
 *         is Aug 27, NOT Aug 28. Jan 26, Apr 06, Jun 07, Jul 06 fall on weekends.
 *  - 2026: NSE/CMTR/71775 (Dec 12 2025) — 16 weekday closures + 4 weekend
 *         holidays (Feb 15, Mar 21, Aug 15, Nov 08). The previous table listed
 *         Aug 27 (Ganesh Chaturthi 2025) as a 2026 holiday and had wrong dates
 *         for Holi, Ram Navami, Mahavir Jayanti, Good Friday, Bakri Id, Muharram,
 *         Dussehra and Guru Nanak — making Thu Aug 27 2026 appear CLOSED while
 *         the exchange is open (Ganesh Chaturthi 2026 is Sep 14).
 */
const NSE_HOLIDAYS: Record<string, string[]> = {
  '2025': [
    '2025-02-26', '2025-03-14', '2025-03-31', '2025-04-10', '2025-04-14', '2025-04-18', '2025-05-01',
    '2025-08-15', '2025-08-27', '2025-10-02', '2025-10-21', '2025-10-22', '2025-11-05', '2025-12-25',
    // Weekend holidays (keep HOLIDAY status on those Saturdays/Sundays):
    '2025-01-26', '2025-04-06', '2025-06-07', '2025-07-06',
  ],
  '2026': [
    '2026-01-15', '2026-01-26', '2026-03-03', '2026-03-26', '2026-03-31', '2026-04-03', '2026-04-14', '2026-05-01',
    '2026-05-28', '2026-06-26', '2026-09-14', '2026-10-02', '2026-10-20', '2026-11-10', '2026-11-24', '2026-12-25',
    // Weekend holidays (market already closed, kept for HOLIDAY vs CLOSED display):
    '2026-02-15', '2026-03-21', '2026-08-15', '2026-11-08',
  ],
};

const IST_OFFSET_MS = 5.5 * 3600_000;

export function istFields(ts: number): { year: number; month: number; day: number; weekday: number; hour: number; minute: number } {
  const ist = new Date(ts + IST_OFFSET_MS);
  return {
    year: ist.getUTCFullYear(),
    month: ist.getUTCMonth() + 1,
    day: ist.getUTCDate(),
    weekday: ist.getUTCDay(), // 0=Sunday
    hour: ist.getUTCHours(),
    minute: ist.getUTCMinutes(),
  };
}

export function istDateKey(ts: number): string {
  const f = istFields(ts);
  return `${f.year}-${String(f.month).padStart(2, '0')}-${String(f.day).padStart(2, '0')}`;
}

export class IndiaMarketSessionService {
  private holidays = new Set<string>();
  private cached: IndiaMarketSessionInfo | null = null;
  private cachedAt = 0;

  constructor(private store: DataStore, private events: EventEmitter) {}

  async init(): Promise<void> {
    // Warn when the hardcoded holiday table doesn't cover the current year —
    // from Jan 1 of the next uncovered year every NSE holiday is treated as a
    // trading day (scans, goal sessions, EOD exits fire on holidays).
    const curYear = new Date().getFullYear().toString();
    if (!NSE_HOLIDAYS[curYear]) {
      // eslint-disable-next-line no-console
      console.warn(`[india] NSE holiday calendar has no entries for ${curYear} — market will be considered OPEN on holidays. Add ${curYear} entries or set INDIA_HOLIDAY_FILE.`);
    }
    // Built-in NSE calendar.
    for (const list of Object.values(NSE_HOLIDAYS)) for (const d of list) this.holidays.add(d);
    // Optional JSON file override.
    if (indiaConfig.holidayFile) {
      try {
        const raw = JSON.parse(fs.readFileSync(path.resolve(indiaConfig.holidayFile), 'utf8')) as string[];
        for (const d of raw) this.holidays.add(d);
      } catch {
        /* missing/invalid holiday file: ignore */
      }
    }
    // Store-backed additions (e.g. an ad-hoc exchange closure).
    try {
      const stored = await this.store.find<{ date: string }>(INDIA_COLLECTIONS.sessions, { kind: 'holiday' });
      for (const s of stored) this.holidays.add(s.date);
    } catch {
      /* collection may not exist yet */
    }
  }

  addHoliday(dateKey: string): void {
    this.holidays.add(dateKey);
    void this.store.insertOne(INDIA_COLLECTIONS.sessions, { kind: 'holiday', date: dateKey }).catch(() => undefined);
  }

  isHoliday(ts: number): boolean {
    return this.holidays.has(istDateKey(ts));
  }

  /**
   * Whether `ts` falls inside a real NSE trading session — the single definition of that
   * question for callers that need to ask it about an arbitrary timestamp.
   *
   * Separate from `snapshot()` for two reasons. `snapshot()` memoises for a second, so it
   * only answers correctly about *now*, and it builds a whole session-info object with
   * pre-open windows and per-segment maps that a yes/no caller does not want on a per-tick
   * path. It is also the fix for a shape of bug this subsystem kept reinventing: the same
   * 09:15–15:30 window was hand-rolled from raw numbers in several modules, each copy free
   * to drift on the boundary and none of them aware of the holiday calendar that lives
   * here. Boundary matches `snapshot()` exactly — open inclusive, close exclusive — so the
   * two can never disagree about the minute of the bell.
   */
  isTradingTime(ts: number): boolean {
    const f = istFields(ts);
    if (f.weekday === 0 || f.weekday === 6) return false;
    if (this.isHoliday(ts)) return false;
    const minutes = f.hour * 60 + f.minute;
    const openMin = INDIA_SESSION.open.hour * 60 + INDIA_SESSION.open.minute;
    const closeMin = INDIA_SESSION.close.hour * 60 + INDIA_SESSION.close.minute;
    return minutes >= openMin && minutes < closeMin;
  }

  /** Current session state, computed from UTC at evaluation time. */
  snapshot(ts = Date.now()): IndiaMarketSessionInfo {
    // Cache for 1s — evaluation happens frequently (tick path).
    //
    // Only for a `ts` at or after the one already computed. The bare `ts - this.cachedAt
    // < 1000` test was also true for every timestamp in the past, by a wide margin, so a
    // caller asking about a historical moment got a snapshot describing the present with
    // no indication that its argument had been ignored.
    if (this.cached && ts >= this.cachedAt && ts - this.cachedAt < 1000) return this.cached;
    const f = istFields(ts);
    const minutes = f.hour * 60 + f.minute;
    const openMin = INDIA_SESSION.open.hour * 60 + INDIA_SESSION.open.minute;
    const closeMin = INDIA_SESSION.close.hour * 60 + INDIA_SESSION.close.minute;
    const preStart = INDIA_SESSION.preOpenStart.hour * 60 + INDIA_SESSION.preOpenStart.minute;
    const preEnd = INDIA_SESSION.preOpenEnd.hour * 60 + INDIA_SESSION.preOpenEnd.minute;

    const weekend = f.weekday === 0 || f.weekday === 6;
    const holiday = this.isHoliday(ts);
    const tradingDay = !weekend && !holiday;
    const marketOpen = tradingDay && minutes >= openMin && minutes < closeMin;
    const preOpen = tradingDay && minutes >= preStart && minutes < preEnd;

    let status: IndiaMarketStatus;
    if (!tradingDay) status = holiday ? 'HOLIDAY' : 'CLOSED';
    else if (preOpen) status = 'PRE_OPEN';
    else if (marketOpen) status = 'OPEN';
    else status = 'CLOSED';

    // Floor to minute so sub-second residue of `ts` (e.g. 12:00:30.500) doesn't
    // carry into the reported 15:30 close as 15:30:30.500, wobbling countdowns.
    const flooredTs = Math.floor(ts / 60_000) * 60_000;
    const f2 = istFields(flooredTs);
    const dayStart = flooredTs - (f2.hour * 60 + f2.minute) * 60_000 - IST_OFFSET_MS;
    const marketOpenAt = tradingDay ? dayStart + openMin * 60_000 + IST_OFFSET_MS : null;
    const marketCloseAt = tradingDay ? dayStart + closeMin * 60_000 + IST_OFFSET_MS : null;

    const info: IndiaMarketSessionInfo = {
      status,
      isHoliday: holiday,
      ist: f,
      marketOpenAt,
      marketCloseAt,
      marketOpen,
      segments: {
        NSE_INDEX: marketOpen,
        NSE_FUT: marketOpen,
        NSE_OPT: marketOpen,
        BSE_INDEX: marketOpen,
        BSE_FUT: marketOpen,
        BSE_OPT: marketOpen,
      },
      generatedAt: ts,
    };
    this.cached = info;
    this.cachedAt = ts;
    return info;
  }

  /** Emit market-status events on open/close transitions. */
  checkTransition(): void {
    const s = this.snapshot();
    const key = `${s.ist.year}-${s.ist.month}-${s.ist.day}:${s.status}`;
    if (this.lastStatusKey !== key) {
      this.lastStatusKey = key;
      this.events.emit(INDIA_CHANNELS.marketStatus, {
        status: s.status,
        marketOpen: s.marketOpen,
        isHoliday: s.isHoliday,
        ist: `${s.ist.hour.toString().padStart(2, '0')}:${s.ist.minute.toString().padStart(2, '0')}`,
        marketOpenAt: s.marketOpenAt,
        marketCloseAt: s.marketCloseAt,
        segments: s.segments,
        generatedAt: Date.now(),
      });
      void this.store.insertOne(INDIA_COLLECTIONS.sessions, { kind: 'status', ...s, timestamp: Date.now() }).catch(() => undefined);
    }
  }

  private lastStatusKey = '';
}